function TrailBattleMgr:__init()
    self.initialed = false
    self.trailSceneGo = nil
    self.co = nil
    self.mapEnv = nil
    self.enterData = nil
    self.isMinSegment = nil--是否为最低段位
    self.isMaxSegment = nil--是非为最高段位
    self.playerTrans = {}
end

function TrailBattleMgr:__delete()
    self.initialed = nil
    self.playerTrans = nil

    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    self.mapEnv = nil
    self.enterData = nil
    self.isMinSegment = nil
    self.isMaxSegment = nil
    self:ResetSettings()
    if not isNull(self.trailSceneGo) then
        KTool.SafeDelete(self.trailSceneGo, true)
    end
    self.trailSceneGo = nil
end

