function TrailBattleMgr:GetUnlistedNumber(start, finish)--获取未上榜人数  分数<=0则未上榜
    start = checkNumber(start)
    finish = checkNumber(finish)
    local num = 0
    for i = start, finish do
        if self.enterData.roomRank[i].score <= 0 then
            num = num + 1
        end
    end
    return num
end

---设置最高最低段位id
function TrailBattleMgr:SetMaxMinSegmentId()
    local segmentRewardVo = CfUtils.GetWholeVo(AutoIds.IdSetting742, "TrailSegmentRewardVo")
    table.sort(segmentRewardVo, function (a,b)--按段位进行排序
        if a.id ~= b.id then
            return a.id < b.id
        end
    end)
    local mySegment = self:GetMySegment()
    --printInfo("mySegment===>>"..mySegment)
    self.isMaxSegment = mySegment == checkNumber(segmentRewardVo[#segmentRewardVo].id)
    self.isMinSegment = mySegment == checkNumber(segmentRewardVo[1].id)
end

