                ---成功请求后
                ---@type TrailEnterDojo
                local trailEnterDojo = TrailEnterDojo.New()
                trailEnterDojo:Fill(response.data)
                self.enterData = trailEnterDojo
                self:SetMaxMinSegmentId()
                ----开始进入试炼
                self.initialed = true
                --if self.mapEnv then
                --    self.mapEnv:UpdateCircle()
                --end
                if cb then
                    cb()
                end
                if checkNumber(trailEnterDojo.isFirst) == 1 then--isFirst改为是否显示弹窗的条件
                    if checkNumber(trailEnterDojo.firstTrial) == 1 then
                        ---如果是初次进入(全局)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStagePopupShow, parameters = {
                            type = TrailBattleMgr.CONSTANTS.POPUP_TYPE.FIRST_ENTRY
                        } })
                    elseif checkNumber(trailEnterDojo.lastSegment) ~= 0 then
                        --if checkInt(trailEnterDojo.lastSegment) ~= checkInt(trailEnterDojo.segment) then
                            --晋级保级降级
                            UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStagePopupShow, parameters = {
                                type = TrailBattleMgr.CONSTANTS.POPUP_TYPE.SEGMENT_CHANGE, lastSegment = checkInt(trailEnterDojo.lastSegment),
                                segment = checkInt(trailEnterDojo.segment), rank = checkInt(trailEnterDojo.rank),
                            } })
                        --end
                    elseif checkNumber(trailEnterDojo.firstTrial) == 0 then
                        ---当前段位（跨段位掉级）
                        UIModule.OpenDialog({ id = Constants.UITypeIds.TrailStagePopupShow, parameters = {
                            type = TrailBattleMgr.CONSTANTS.POPUP_TYPE.MANY_SEASON_NOT_JOIN,
                            segment = checkInt(trailEnterDojo.segment),
                        } })

                    end
                else
                    Events.Broadcast(Constants.EventNames.PlayTrailLevelAnim)
                end

                Events.Broadcast(Constants.EventNames.RefeshTrailQuestDialog, nil)
            else
                if errCB then
                    errCB()
                end
            end
        end)
    --end
