---InitialPlayers
---@param root UnityEngine.GameObject
---@param catPrefab UnityEngine.GameObject
function TrailBattleMgr:InitialPlayers(root, catPrefab)
    self:ResetCirclePlayers(root)
    ---设置人物角色
    self.playerTrans = {}
    local location = 1
    ---@type TrailSegmentRewardVo
    local segmentVo = self:GetSegmentRewardVoByRefId(self.enterData.segment)
    local segmentSpanUp, segmentSpanStay, segmentSpanDown = 0, 0, 0
    if segmentVo.upGrade ~= 0 then
        segmentSpanUp = checkInt(segmentVo.upGrade[2]) - checkInt(segmentVo.upGrade[1]) + 1
    end
    if segmentVo.keepGrade ~= 0 then
        segmentSpanStay = checkInt(segmentVo.keepGrade[2]) - checkInt(segmentVo.keepGrade[1]) + 1
    end
    if segmentVo.downGrade ~= 0 then
        segmentSpanDown = checkInt(segmentVo.downGrade[2]) - checkInt(segmentVo.downGrade[1]) + 1
    end

    local deltaAngle = HALF_ANGLE / (segmentSpanUp + segmentSpanStay + segmentSpanDown)

    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComponent.playerDojo.playerId

    local startAngle = LEFT_MAX_POINT_NUM
    for seqNo, v in pairs(self.enterData.roomRank) do
        local catNodeGo = KTool.Instantiate(root.gameObject, catPrefab.gameObject, false)
        KTool.SetActive(catNodeGo, true)
        local catMB = GetLuaBehaviour(catNodeGo, TrailMapPlayerNodeLuaPath)
        if not isNull(catMB) then
            if isNull(catMB.Env) then
                catMB:Init()
            end
            ---@type TrailMapPlayerNode
            local env = catMB.Env
            env:FreshPlayer(seqNo, v.name, v.score, checkInt(playerId) == checkInt(v.playerId), checkInt(v.image))
        end
        if checkInt(v.score) > 0 then
            ---存在评分的情况下有排名
            local startLocation = 1
            local meta = 0
            if segmentSpanUp > 0 and seqNo <= segmentSpanUp then
                startAngle = HALF_ANGLE - 1
                meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[1].score) * deltaAngle * segmentSpanUp)
                startLocation = seqNo
                if checkInt(v.score) / self.enterData.roomRank[1].score >= 0.5 then
                    meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[1].score) * deltaAngle * segmentSpanUp) + (startLocation - 1) * 3
                else
                    --meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + 1].score) * deltaAngle * segmentSpanStay)
                    meta = startLocation * deltaAngle - 3
                end
            elseif segmentSpanStay > 0 and seqNo > segmentSpanUp and seqNo <= (segmentSpanUp + segmentSpanStay) then
                startAngle = (HALF_ANGLE - deltaAngle * segmentSpanUp) - 1
                startLocation = (seqNo - segmentSpanUp)
                if checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + 1].score >= 0.5 then
                    meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + 1].score) * deltaAngle * segmentSpanStay) + (startLocation - 1) * 3
                else
                    --meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + 1].score) * deltaAngle * segmentSpanStay)
                    meta = startLocation * deltaAngle - 3
                end

                --print(startAngle, startLocation, meta, startLocation % 3)
                --self:BuildPlayer(catNodeGo, seqNo, startAngle, startLocation, meta)

            elseif segmentSpanDown > 0 and seqNo > (segmentSpanUp + segmentSpanStay) then
                startAngle = (deltaAngle * segmentSpanDown) - 1
                startLocation = (seqNo - segmentSpanUp - segmentSpanStay)
                --meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + segmentSpanStay + 1].score) * deltaAngle * segmentSpanDown)
                if checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + segmentSpanStay + 1].score >= 0.5 then
                    meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + segmentSpanStay + 1].score) * deltaAngle * segmentSpanDown) + (startLocation - 1) * 3
                else
                    --meta = math.floor((1 - checkInt(v.score) / self.enterData.roomRank[segmentSpanUp + 1].score) * deltaAngle * segmentSpanStay)
                    meta = startLocation * deltaAngle - 3
                end
            end
            self:BuildPlayer(catNodeGo, seqNo, startAngle, startLocation, meta, checkInt(v.playerId))
        else
            ---属于启始区
            self:BuildPlayer(catNodeGo, seqNo, CIRCLE_ANGLE - 1, location, (location - 1) * 3, checkInt(v.playerId))
            location = location + 1
        end
    end
    self:OnUpdate(0)
end

---GetStartPositionByAngle
---根据玩家节点位置的角色获取出圆型画图数据的index起点位置
---@param angle number
function TrailBattleMgr:GetStartPositionByAngle(angle)
    if angle >= 0 then
        return angle * 2
    else
        return (CIRCLE_ANGLE + angle) * 2
    end
end

---GetPlayerNodeUIPosition
---@param angle number
---@param index number
function TrailBattleMgr:GetPlayerNodeUIPosition(angle, index)
    local mod = index % 3
    local size = { x = 48, y = 86 }
    if mod == 0 then
        size = { x = size.x, y = 1800 * 1.5 - Mathf.Cos(angle) * TrailBattleMgr.CONSTANTS.DELTA_Y }
    elseif mod == 1 then
        size = { x = size.x, y = 1980 * 1.5 - Mathf.Cos(angle) * TrailBattleMgr.CONSTANTS.DELTA_Y }
    elseif mod == 2 then
        size = { x = size.x, y = 1910 * 1.5 - Mathf.Cos(angle) * TrailBattleMgr.CONSTANTS.DELTA_Y }
    end
    return size
end

---OnUpdate
---更新ui界面的相关的逻辑
function TrailBattleMgr:OnUpdate(angleMove)
    if self.playerTrans and #self.playerTrans > 0 then
        --print('--->>>', angleMove)
        for i, v in pairs(self.playerTrans) do
            local deltaAngle = (v.angle - angleMove)
            --local delta = deltaAngle - CIRCLE_ANGLE
            local delta = deltaAngle
            if deltaAngle > 180 then
                delta = deltaAngle - CIRCLE_ANGLE
            end
            local angle = Mathf.Deg2Rad * deltaAngle
            if delta > TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_LEFT and delta < TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_RIGHT then
                v.canvasGroup.alpha = 1
                v.alpha = 1
            elseif delta >= TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_RIGHT and delta < TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_RIGHT + 2 then
                local alpha = 0.5 * (TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_RIGHT + 2 - delta)
                v.canvasGroup.alpha = alpha
                v.alpha = alpha
            elseif delta > (TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_LEFT - 2) and delta <= TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_LEFT then
                local alpha = 0.5 * (delta + 2 - TrailBattleMgr.CONSTANTS.SCREEN_ANGLE_LEFT)
                v.canvasGroup.alpha = alpha
                v.alpha = alpha
            else
                v.canvasGroup.alpha = 0
                v.alpha = 0
            end
            local x = Mathf.Sin(angle) * TrailBattleMgr.CONSTANTS.DELTA_Y
            local y = Mathf.Cos(angle) * TrailBattleMgr.CONSTANTS.DELTA_Y - 60
            if v.alpha > 0 then
                local size = self:GetPlayerNodeUIPosition(angle, v.location)
                v.catRectTrans.anchoredPosition = Vector2.New(x, y)
                v.billboardTrans.sizeDelta = size
                v.bottomTrans:SetRotationZ(-delta)
            end
        end
    end
end

---GetSegment
---获取当前我的段位
function TrailBattleMgr:GetMySegment()
    return checkNumber(self.enterData.segment)
end

function TrailBattleMgr:GetEnterData()
    return checkTable(self.enterData)
end

---GetMyRoomRankInfo
---获取我当前在房间排名的信息
function TrailBattleMgr:GetMyRoomRankInfo()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerId = playerComponent.playerDojo.playerId
    local info = nil
    for i, v in pairs(self.enterData.roomRank) do
        if checkInt(v.playerId) == checkNumber(playerId) then
            info = v
            break
        end
    end
    return info
end

---GetMyRankGroupBySegment
---根据当前的段位及排名得出所以的分组的逻辑
---@param segment number
function TrailBattleMgr:GetRankGroupBySegment(segment)
    local rank = checkInt(self.enterData.rank) ---当前我的排名
    ---@type TrailSegmentRewardVo
    local segmentVo = self:GetSegmentRewardVoByRefId(segment)
    local segmentSpanUp, segmentSpanStay, segmentSpanDown = 0, 0, 0
    if segmentVo.upGrade ~= 0 then
        segmentSpanUp = checkInt(segmentVo.upGrade[2]) - checkInt(segmentVo.upGrade[1]) + 1
    end
    if segmentVo.keepGrade ~= 0 then
        segmentSpanStay = checkInt(segmentVo.keepGrade[2]) - checkInt(segmentVo.keepGrade[1]) + 1
    end
    if segmentVo.downGrade ~= 0 then
        segmentSpanDown = checkInt(segmentVo.downGrade[2]) - checkInt(segmentVo.downGrade[1]) + 1
    end


    if rank == 0 then
        ---起始区
        return rank, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON
    end
    if rank <= segmentSpanUp then
        ---晋级组
        return rank, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON
    elseif rank > segmentSpanUp and rank <= segmentSpanUp + segmentSpanStay then
        ---保级组
        return rank, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON
    else
        ---降级组
        return rank, TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON
    end
end

---GetSegmentRewardVoBySegment
---根据段位得到段位奖励信息
---@param segment number
---@return TrailSegmentRewardVo
function TrailBattleMgr:GetSegmentRewardVoBySegment(segment)
    if segment == -1 then
        ---128名的奖励
        local setting = settingMgr:GetSetting(AutoIds.IdSetting741, "TrailSegmentRewardVo")
        return setting:Get(segment)
    else
        local setting = settingMgr:GetSetting(AutoIds.IdSetting742, "TrailSegmentRewardVo")
        return setting:Get(segment)
    end
end

---GetSegmentIconPath
---@param segment number
---@param isBig boolean
function TrailBattleMgr:GetSegmentIconPath(segment, isBig)
    isBig = checkBool(isBig)
    if isBig then
        return string.format('uiatlas/trailstage/competition_common_ico_rank_%d.png', checkNumber(segment) / 100)
    else
        return string.format('uiatlas/trailstage/competition_main_ico_rank_%d.png', checkNumber(segment) / 100)
    end
end

---GetRankGroupIconPath
---@param group number
function TrailBattleMgr:GetRankGroupIconPath(group)
    return string.format('uiatlas/trailstage/competition_main_ico_group_%d.png', checkNumber(group) - 1)
end

---
---@param turn number 关卡的索引
function TrailBattleMgr:IsUnlockQuest(turn)
    turn = checkNumber(turn)
    local curSegment = self:GetMySegment()
    local segmentData = self:GetSegmentRewardVoByRefId(curSegment)
    local isUnlock = segmentData.roundNum >= turn
    return isUnlock
end

return TrailBattleMgr